namespace Atc.Rest.Api.Generator.Tests.Helpers;

public class PolicyConstantsClassBuilderTests
{
    [Fact]
    public void Build_TwoConstants_WritesTheWholeFile()
    {
        var constants = new[]
        {
            new PolicyConstant("Short", "short", "Policy: 30 seconds"),
            new PolicyConstant("Legacy", "legacy", "Policy: 5 minutes", "[Obsolete(\"Use Short\")]"),
        };

        var content = PolicyConstantsClassBuilder.Build("MyApi", "Caching", "OutputCachePolicies", "Output cache policy names.", constants);

        var expected =
            "// <auto-generated />" + Environment.NewLine +
            "#nullable enable" + Environment.NewLine +
            Environment.NewLine +
            "using System.CodeDom.Compiler;" + Environment.NewLine +
            Environment.NewLine +
            "namespace MyApi.Generated.Caching;" + Environment.NewLine +
            Environment.NewLine +
            "/// <summary>" + Environment.NewLine +
            "/// Output cache policy names." + Environment.NewLine +
            "/// </summary>" + Environment.NewLine +
            $"[GeneratedCode(\"Atc.Rest.Api.SourceGenerator\", \"{GeneratorInfo.Version}\")]" + Environment.NewLine +
            "public static class OutputCachePolicies" + Environment.NewLine +
            "{" + Environment.NewLine +
            "    /// <summary>" + Environment.NewLine +
            "    /// Policy: 30 seconds" + Environment.NewLine +
            "    /// </summary>" + Environment.NewLine +
            "    public const string Short = \"short\";" + Environment.NewLine +
            Environment.NewLine +
            "    /// <summary>" + Environment.NewLine +
            "    /// Policy: 5 minutes" + Environment.NewLine +
            "    /// </summary>" + Environment.NewLine +
            "    [Obsolete(\"Use Short\")]" + Environment.NewLine +
            "    public const string Legacy = \"legacy\";" + Environment.NewLine +
            "}" + Environment.NewLine;
        Assert.Equal(expected, content);
    }

    [Fact]
    public void AppendClass_WithConstants_ReturnsTrueAndLeavesTheClassOpen()
    {
        var builder = new StringBuilder();

        var any = PolicyConstantsClassBuilder.AppendClass(
            builder,
            "MyApi",
            "Security",
            "SecurityPolicies",
            "Authorization policy names.",
            [new PolicyConstant("AdminOnly", "admin-only", "Requires the admin role")]);

        Assert.True(any);
        var content = builder.ToString();
        Assert.Contains("namespace MyApi.Generated.Security;", content, StringComparison.Ordinal);
        Assert.Contains("public static class SecurityPolicies", content, StringComparison.Ordinal);
        Assert.EndsWith("    public const string AdminOnly = \"admin-only\";" + Environment.NewLine, content, StringComparison.Ordinal);
    }

    [Fact]
    public void AppendClass_NoConstants_ReturnsFalseAndWritesOnlyTheSkeleton()
    {
        var builder = new StringBuilder();

        var any = PolicyConstantsClassBuilder.AppendClass(builder, "MyApi", "Resilience", "ResiliencePolicies", "Resilience policy names.", []);

        Assert.False(any);
        var content = builder.ToString();
        Assert.EndsWith("public static class ResiliencePolicies" + Environment.NewLine + "{" + Environment.NewLine, content, StringComparison.Ordinal);
        Assert.DoesNotContain("public const", content, StringComparison.Ordinal);
    }

    [Fact]
    public void AppendClass_NullArguments_Throw()
    {
        Assert.Throws<ArgumentNullException>(() => PolicyConstantsClassBuilder.AppendClass(null!, "MyApi", "Caching", "C", "S", []));
        Assert.Throws<ArgumentNullException>(() => PolicyConstantsClassBuilder.AppendClass(new StringBuilder(), "MyApi", "Caching", "C", "S", null!));
    }
}